const allowed = new Set(['PAYMENT_FAILED','ACCOUNT_SECURITY_ANOMALY','CANCELLATION_DEADLINE_3D','RENEWAL_3D_HIGH_RISK','UNEXPECTED_HIGH_CHARGE']);
return items.map((item) => {
  const e = item.json || {};
  if (!allowed.has(e.ruleId)) throw new Error('SMS alert rule not allowed');
  if (e.severity !== 'URGENT') throw new Error('SMS requires URGENT severity');
  const vendor = String(e.vendor || e.service || 'Subscription').slice(0,80);
  const reason = String(e.summary || e.reason || e.ruleId).slice(0,130);
  const detail = String(e.deadline || e.amount || '').slice(0,45);
  let message = `Subscription Ops: ${vendor} — ${reason}${detail ? ` (${detail})` : ''}. Review required. No action was taken.`;
  if (message.length > 320) message = message.slice(0,298) + ' No action was taken.';
  return { json: { mode:'DRY_RUN', ruleId:e.ruleId, severity:'URGENT', recipient:'FIXED_OWNER_NUMBER_RUNTIME_ONLY', message, sendAuthorized:false, externalActions:0 } };
});
